export class MusicLibrary{
 constructor({audio,input,list,title,subtitle,notify,onTrack,onChange}){
  Object.assign(this,{audio,input,list,title,subtitle,notify,onTrack,onChange});this.tracks=[];this.selected=null;this.url=null;this.db=null;this.dbPromise=this.open();this.dbPromise.catch(()=>{});
  input.multiple=true;input.onchange=()=>this.importFiles([...input.files]);
  audio.addEventListener('ended',()=>this.next());
  audio.addEventListener('error',()=>{if(this.selected)this.notify('Bu ses biçimi tarayıcıda oynatılamıyor.');});
  audio.addEventListener('pause',()=>this.persistPlayback());audio.addEventListener('timeupdate',()=>{if(Date.now()-(this.lastSaved||0)>3000){this.persistPlayback();this.lastSaved=Date.now();}});
  audio.addEventListener('play',()=>this.render());audio.addEventListener('pause',()=>this.render());
 }
 async open(){try{const req=indexedDB.open('yigit-studio-audio',1);this.db=await new Promise((resolve,reject)=>{req.onupgradeneeded=()=>{if(!req.result.objectStoreNames.contains('tracks'))req.result.createObjectStore('tracks',{keyPath:'id'});};req.onsuccess=()=>resolve(req.result);req.onerror=()=>reject(req.error);req.onblocked=()=>reject(Error('blocked'));});await this.refresh();let saved;try{saved=JSON.parse(localStorage.getItem('yigit-playback')||'null');}catch{}if(saved&&this.tracks.some(t=>t.id===saved.id))await this.select(saved.id,false,saved.time||0);return this.db;}catch(e){this.notify('Ses kitaplığı bu tarayıcıda açılamadı.');this.list.textContent='Depolama kullanılamıyor.';throw e;}}
 async request(mode,fn){const db=this.db||await this.dbPromise;return new Promise((resolve,reject)=>{const tx=db.transaction('tracks',mode);let result;try{let req=fn(tx.objectStore('tracks'));req.onsuccess=()=>result=req.result;}catch(e){reject(e);return;}tx.oncomplete=()=>resolve(result);tx.onerror=()=>reject(tx.error);tx.onabort=()=>reject(tx.error||Error('aborted'));});}
 async refresh(){this.tracks=(await this.request('readonly',s=>s.getAll())).sort((a,b)=>a.added-b.added);this.render();this.onChange?.(this.tracks);}
 async importFiles(files){let count=0;for(const f of files){if(!f.type.startsWith('audio/')&&!/\.(mp3|wav|ogg|m4a|aac|flac|webm|opus)$/i.test(f.name))continue;try{await this.dbPromise;let id=f.name+'|'+f.size+'|'+f.lastModified;await this.request('readwrite',s=>s.put({id,name:f.name,size:f.size,added:Date.now(),blob:f}));count++;}catch(e){this.notify('Dosya saklanamadı. Tarayıcı depolama alanı dolu veya kapalı olabilir.');break;}}this.input.value='';if(count){await this.refresh();this.notify(count+' ses dosyası kitaplığa eklendi.');}}
 async select(id,play=true,resume=0){const track=this.tracks.find(t=>t.id===id);if(!track)return;this.audio.pause();if(this.url)URL.revokeObjectURL(this.url);this.selected=id;this.url=URL.createObjectURL(track.blob);this.audio.src=this.url;this.audio.onloadedmetadata=()=>{if(resume)this.audio.currentTime=Math.min(resume,this.audio.duration||resume);};this.title.textContent=track.name;this.subtitle.textContent='Ses kitaplığı';this.onTrack?.(track);this.render();this.persistPlayback();if(play)try{await this.audio.play();}catch{this.notify('Oynatmak için tekrar dokun.');}}
 async toggle(){if(!this.selected){const first=this.tracks[0];if(first)await this.select(first.id);else this.input.click();return;}if(this.audio.paused)try{await this.audio.play();}catch{this.notify('Ses dosyası oynatılamadı.');}else this.audio.pause();}
 async next(direction=1){if(!this.tracks.length)return;const i=this.tracks.findIndex(t=>t.id===this.selected);await this.select(this.tracks[(i+direction+this.tracks.length)%this.tracks.length].id);}
 async remove(id){try{await this.request('readwrite',s=>s.delete(id));if(this.selected===id){this.audio.pause();this.audio.removeAttribute('src');this.audio.load();this.selected=null;this.onTrack?.(null);this.title.textContent='Müzik';this.subtitle.textContent='Kitaplıktan bir parça seç';try{localStorage.removeItem('yigit-playback');}catch{}}await this.refresh();}catch{this.notify('Dosya kaldırılamadı.');}}
 persistPlayback(){if(this.selected)try{localStorage.setItem('yigit-playback',JSON.stringify({id:this.selected,time:this.audio.currentTime||0}));}catch{}}
 render(){this.list.replaceChildren();if(!this.tracks.length){const empty=document.createElement('p');empty.className='library-empty';empty.textContent='Henüz ses dosyası yok.';this.list.append(empty);return;}for(let track of this.tracks){const row=document.createElement('div');row.className='track-row'+(track.id===this.selected?' active':'');const play=document.createElement('button');play.className='track-play';play.setAttribute('aria-label',track.name+' çal');play.textContent=track.id===this.selected&&!this.audio.paused?'Ⅱ':'▶';play.onclick=()=>track.id===this.selected?this.toggle():this.select(track.id);const name=document.createElement('button');name.className='track-name';name.textContent=track.name;name.title=track.name;name.onclick=()=>this.select(track.id);const size=document.createElement('small');size.textContent=(track.size/1048576).toFixed(1)+' MB';const remove=document.createElement('button');remove.className='track-remove';remove.textContent='×';remove.setAttribute('aria-label',track.name+' kaldır');remove.onclick=()=>this.remove(track.id);row.append(play,name,size,remove);this.list.append(row);}}
}
